const int buttonPin = {{button_pin}};
const unsigned long debounceMs = {{debounce_ms}};
volatile unsigned long lastIsr = 0;
volatile bool pressedFlag = false;

void IRAM_ATTR handleButton() {
  unsigned long now = millis();
  if (now - lastIsr > debounceMs) {
    pressedFlag = true;
    lastIsr = now;
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(buttonPin, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(buttonPin), handleButton, FALLING);
}

void loop() {
  if (pressedFlag) {
    pressedFlag = false;
    Serial.println("button event");
  }
}
